// This file is generated by AI.

// Fluent UI 的 Dropdown 使用 inlinePopup, 保留下拉选项在控件附近渲染, 避免 Tauri WebView
// 中 portal 弹层的已知渲染异常。

import { Dropdown, Option } from '@fluentui/react-components';
import { ChevronDownRegular } from '@fluentui/react-icons';

export interface SelectOption {
  value: string;
  label: string;
}

interface Props {
  value: string;
  options: SelectOption[];
  onChange: (value: string) => void;
  /** 无障碍标签与悬浮提示 */
  title?: string;
  disabled?: boolean;
  /** 触发按钮的占位文本 (值为空时显示) */
  placeholder?: string;
  className?: string;
}

export function Select({ value, options, onChange, title, disabled, placeholder, className }: Props) {
  return (
    <div className={`select${className ? ` ${className}` : ''}`}>
      <Dropdown
        className="select-trigger"
        value={options.find((option) => option.value === value)?.label ?? value}
        selectedOptions={options.some((option) => option.value === value) ? [value] : []}
        placeholder={placeholder}
        title={title}
        disabled={disabled}
        inlinePopup
        expandIcon={{ children: <ChevronDownRegular className="select-chevron" /> }}
        onOptionSelect={(_, data) => {
          if (data.optionValue !== undefined) onChange(data.optionValue);
        }}
      >
        {options.map((option) => (
          <Option key={option.value} value={option.value} text={option.label}>
            {option.label}
          </Option>
        ))}
      </Dropdown>
    </div>
  );
}

/** 由 `Record<string, string>` 构造选项 (键序即显示顺序) */
export function toOptions(labels: Record<string, string>): SelectOption[] {
  return Object.entries(labels).map(([value, label]) => ({ value, label }));
}
